  options.Scale=50;var second=DlssCore.Prepare(game,options,null,"settings");DlssCore.Apply(game,second);Check(DlssCore.ReadManifest(game.Root).Files.Count==3,"baseline duplicates");var undo=DlssCore.PrepareUninstall(game);DlssCore.Apply(game,undo);Check(!File.Exists(Path.Combine(game.Root,"dxgi.dll")),"new proxy not removed");Check(File.ReadAllText(Path.Combine(game.Root,"OptiScaler.ini")).Contains(";preserve"),"original ini not restored");Check((File.GetAttributes(Path.Combine(game.Root,"OptiScaler.ini"))&FileAttributes.ReadOnly)!=0,"readonly lost");
  plan=DlssCore.Prepare(game,options,package,"test");File.WriteAllText(Path.Combine(game.Root,"dxgi.dll"),"new external mod");Reject(()=>DlssCore.Apply(game,plan),"stale preview accepted");Check(File.ReadAllText(Path.Combine(game.Root,"dxgi.dll"))=="new external mod","stale file overwritten");File.Delete(Path.Combine(game.Root,"dxgi.dll"));
