 public static void Package(string archive,string folder){Directory.CreateDirectory(folder);string package=DlssCore.Unpack(archive,Path.Combine(folder,"extracted"));Core.Data=Path.Combine(folder,"data");var g=new Game{Id="test",Name="Package test",Root=Path.Combine(folder,"game"),Exe=Path.Combine(folder,"game","Test.exe")};FakePe(g.Exe,false);FakePe(Path.Combine(g.Root,"nvngx_dlssnr.dll"),false);var plan=DlssCore.Prepare(g,new DlssOptions(),package,"archive test");Check(plan.Changes.Any(c=>c.Name=="dxgi.dll"),"main DLL missing");Check(plan.Changes.Any(c=>c.Name.StartsWith("OptiScaler/")),"backend missing");Check(plan.Changes.All(c=>!c.Name.EndsWith(".exe")&&!c.Name.EndsWith(".bat")),"executable installer copied");File.WriteAllText(Path.Combine(folder,"package-test.txt"),"PASS: archive listing/path validation, complete x64 package recognition, installation plan with "+plan.Changes.Count+" files; no package code executed.\n"+plan.ToString());}
 public static void NativeTest(string source,string folder){Directory.CreateDirectory(folder);Core.Data=Path.Combine(folder,"data");Directory.CreateDirectory(Core.Data);var g=new Game{Id="native-test",Name="DLL test",Root=Path.Combine(folder,"game"),Exe=Path.Combine(folder,"game","Game.exe")};FakePe(g.Exe,false);string dest=Path.Combine(g.Root,"Engine","Plugins","nvngx_dlss.dll");FakePe(dest,false);string original=DlssCore.Hash(dest);var target=DlssLibraries.Scan(g).Single();Reject(()=>DlssLibraries.Validate(source,"nvngx_dlssd.dll"),"SR accepted as RR");var plan=DlssLibraries.Prepare(g,target,source);DlssCore.Apply(g,plan);Check(DlssCore.Hash(dest)==DlssCore.Hash(source),"native DLL swap failed");Reject(()=>DlssLibraries.Prepare(g,target,source),"identical swap accepted");var restore=DlssLibraries.Restore(g);DlssCore.Apply(g,restore);Check(DlssCore.Hash(dest)==original,"native baseline not restored");File.WriteAllText(Path.Combine(folder,"native-test.txt"),"PASS: signed NVIDIA SR validation; wrong component rejected; nested game DLL swap; identical update rejected; original baseline restored. Only fixture modified.");}
 public static void NativeInspect(string root,string report){var g=new Game{Root=root};var files=DlssLibraries.Scan(g);var text=new System.Text.StringBuilder();foreach(var f in files){text.AppendLine(f.ToString());try{DlssLibraries.Validate(f.Path,f.File);text.AppendLine("Signature and component: PASS");}catch(Exception e){text.AppendLine("Signature validation: "+e.Message);}}File.WriteAllText(report,text.ToString());}
 public static void Scan(string exe,string output){var g=new Game{Id="test",Name="Gioco",Root=Path.GetDirectoryName(exe),Exe=exe};File.WriteAllText(output,DlssCore.Inspect(g).ToString());}
 public static void Preview(string exe,string output){new Application();Window owner;using(var s=System.Reflection.Assembly.GetExecutingAssembly().GetManifestResourceStream("Main.xaml"))owner=(Window)System.Windows.Markup.XamlReader.Load(s);owner.Show();var g=new Game{Id="5184670",Name="Clive Barker’s Hellraiser: Revival Demo",Root=Path.GetDirectoryName(exe),Exe=exe};var ui=new DlssUi();var window=ui.Create(owner,g);window.Show();window.UpdateLayout();var b=new RenderTargetBitmap((int)window.ActualWidth,(int)window.ActualHeight,96,96,PixelFormats.Pbgra32);b.Render(window);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(b));using(var f=File.Create(output))encoder.Save(f);window.Close();owner.Close();}
